using System;using System.IO;using System.Linq;using UnityEngine;using ProjectWait.M.Elevator;public static class InspectEyes {public static string Main(){var l=UnityEngine.Object.FindFirstObjectByType<ElevatorLesson>();var head=l.friend.GetComponentsInChildren<Transform>().First(t=>t.name=="head");var skin=l.friend.GetComponentsInChildren<SkinnedMeshRenderer>().First(t=>!t.name.StartsWith("SkyGlow"));var source=skin.sharedMesh;var mesh=new Mesh();skin.BakeMesh(mesh);var b=source.GetBlendShapeIndex("Blink");var v=new Vector3[source.vertexCount];source.GetBlendShapeFrameVertices(b,0,v,null,null);var pts=Enumerable.Range(0,v.Length).Where(i=>v[i].sqrMagnitude>0.000000001f).Select(i=>head.InverseTransformPoint(skin.transform.TransformPoint(mesh.vertices[i]))).ToArray();var json=Newtonsoft.Json.JsonConvert.SerializeObject(new{count=pts.Length,left=(pts.Where(p=>p.x<0).Aggregate(Vector3.zero,(s,p)=>s+p)/Mathf.Max(1,pts.Count(p=>p.x<0))).ToString("F5"),right=(pts.Where(p=>p.x>=0).Aggregate(Vector3.zero,(s,p)=>s+p)/Mathf.Max(1,pts.Count(p=>p.x>=0))).ToString("F5"),min=new Vector3(pts.Min(p=>p.x),pts.Min(p=>p.y),pts.Min(p=>p.z)).ToString("F5"),max=new Vector3(pts.Max(p=>p.x),pts.Max(p=>p.y),pts.Max(p=>p.z)).ToString("F5")},Newtonsoft.Json.Formatting.Indented);UnityEngine.Object.DestroyImmediate(mesh);File.WriteAllText("Assets/M/CodexTemp/ElevatorCoping_20261030~/EyeGeometry.json",json);return json;}}